#!/usr/bin/env bash
# W1 policies v5: NTC-full (adaptive) — slow tier picks (signal, param) on warm-up.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing W1 policies v5 (NTC-full adaptive)..."
decode "scripts/ntc_w1_policies.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Run all three (instant):"
echo "  python scripts/ntc_w1_policies.py --probes experiments/ntc/w1_math500_Qwen3-4B.json --warmup-frac 0.4"
echo "  python scripts/ntc_w1_policies.py --probes experiments/ntc/w1_gsm8k_Qwen3-4B.json --warmup-frac 0.4"
echo "  python scripts/ntc_w1_policies.py --probes experiments/ntc/w1_gpqa16k_Qwen3-4B.json --warmup-frac 0.4"